// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  interpolateColors,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');
const loadInter = makeLoadFont('Inter');

// Module-level Google Font loading
const { fontFamily: montserratFamily } = loadMontserrat();
const { fontFamily: interFamily } = loadInter();

// Dynamic default layers representing the systems thinking Iceberg Model
const defaultLayers = [
  {
    title: "Visible Events",
    subtitle: "What is happening right now?",
    description: "The immediate occurrences or symptoms that we can directly observe, measure, and react to.",
    depthLabel: "VISIBLE SURFACE (10%)",
    visiblePercent: 100,
  },
  {
    title: "Patterns & Trends",
    subtitle: "What has been happening over time?",
    description: "The historical context and recurring behaviors that suggest these events are not isolated incidents.",
    depthLabel: "SHALLOW SUBMERGED (30%)",
    visiblePercent: 70,
  },
  {
    title: "Systemic Structures",
    subtitle: "What rules or relationships drive this?",
    description: "The organizational policies, physical systems, or power structures that influence and generate the patterns.",
    depthLabel: "DEEP SUBMERGED (60%)",
    visiblePercent: 40,
  },
  {
    title: "Mental Models",
    subtitle: "What deep beliefs keep this alive?",
    description: "The underlying values, core assumptions, culture, and worldviews that form the bedrock of the entire system.",
    depthLabel: "SYSTEM BEDROCK (90%)",
    visiblePercent: 10,
  }
];

// Single inline schema declaration as required


export type ComponentNameProps = Record<string, any>;

const IcebergModel: React.FC<ComponentNameProps> = ({
  backgroundColor = "#030f26",
  transparentBackground = false,
  durationInSeconds = 12,
  titleText = "The Iceberg Model",
  subtitleText = "A systems thinking framework for uncovering root causes",
  layers = defaultLayers,
  icebergColorAbove = "#e6f4f8",
  icebergColorBelow = "#1b728a",
  waterlineColor = "#3df2ff",
  highlightColor = "#fcd34d",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parse Safety: Safely resolve layers from array or potential stringified JSON
  const resolvedLayers = React.useMemo(() => {
    if (typeof layers === "string") {
      try {
        const parsed = JSON.parse(layers);
        if (Array.isArray(parsed)) {
          return parsed as typeof defaultLayers;
        }
      } catch (e) {
        // fallback
      }
      return defaultLayers;
    }
    return (layers || defaultLayers) as typeof defaultLayers;
  }, [layers]);

  // Parse Safety: Extract background style calculations
  const bgGradient = transparentBackground
    ? "transparent"
    : `radial-gradient(circle at 40% 30%, #0d254b 0%, ${backgroundColor} 100%)`;

  const durationInFrames = durationInSeconds * fps;

  // Camera breathing effect to make the canvas feel organic and premium
  const cameraScale = interpolate(frame, [0, durationInFrames], [1, 1.03], {
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.25, 1, 0.5, 1),
  });

  // Iceberg Core Layout Dimensions
  const centerX = width * 0.23;
  const waterlineY = height * 0.32;

  // Above Water Iceberg Entrance Timing
  const springAbove = spring({
    frame: frame - 10,
    fps,
    config: { damping: 13, mass: 0.9 },
  });
  const aboveScale = interpolate(springAbove, [0, 1], [0, 1], {
    extrapolateRight: "clamp",
  });
  const aboveY = interpolate(springAbove, [0, 1], [30, 0], {
    extrapolateRight: "clamp",
  });

  // Waterline Sweep Animation Timing
  const springWater = spring({
    frame: frame - 25,
    fps,
    config: { damping: 14 },
  });
  const waterWidth = interpolate(springWater, [0, 1], [0, width * 0.34], {
    extrapolateRight: "clamp",
  });
  const waterOpacity = interpolate(springWater, [0, 1], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Under-Water Mass Reveal Timing
  const springBelow = spring({
    frame: frame - 40,
    fps,
    config: { damping: 16, mass: 1.2 },
  });
  const belowScaleX = interpolate(springBelow, [0, 1], [0.4, 1], {
    extrapolateRight: "clamp",
  });
  const belowScaleY = interpolate(springBelow, [0, 1], [0.1, 1], {
    extrapolateRight: "clamp",
  });
  const belowOpacity = interpolate(springBelow, [0, 1], [0, 0.9], {
    extrapolateRight: "clamp",
  });

  // Subsea Deep Gradient Glow
  const waterDepthOpacity = interpolate(springWater, [0, 1], [0, 0.55], {
    extrapolateRight: "clamp",
  });

  // Dynamic timelines based on total duration
  const revealStart = durationInFrames * 0.15;
  const revealEnd = durationInFrames * 0.85;
  const revealSpan = revealEnd - revealStart;
  const stepSpan = revealSpan / Math.max(1, resolvedLayers.length);

  // Stagger calculations for cards & connection lines
  const layerStaggers = resolvedLayers.map((_, index) => {
    const startFrame = revealStart + index * stepSpan;
    return spring({
      frame: frame - startFrame,
      fps,
      config: { damping: 15, mass: 0.8 },
    });
  });

  // Highlights currently focused items sequentially
  const getFocusWeight = (index: number) => {
    const start = revealStart + index * stepSpan;
    const end = start + stepSpan;
    if (frame < start) return 0;
    if (frame > revealEnd) return 0.5; // settle in unified glorious presentation
    if (frame > end) return 0.25; // keep visible in background
    return interpolate(frame, [start, start + 8, end - 6, end], [0, 1, 1, 0.25], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
  };

  // Iceberg Polygon Vertices
  const pTop = [centerX, height * 0.12];
  const pLeftWater = [centerX - width * 0.08, waterlineY];
  const pRightWater = [centerX + width * 0.08, waterlineY];
  const pMidAbove = [centerX - width * 0.015, waterlineY - height * 0.08];
  const pMidAboveRight = [centerX + width * 0.025, waterlineY - height * 0.06];
  const pCenterWater = [centerX + width * 0.005, waterlineY];

  const pDeepTip = [centerX - width * 0.01, height * 0.88];
  const pLeftBulge = [centerX - width * 0.12, height * 0.54];
  const pRightBulge = [centerX + width * 0.13, height * 0.58];
  const pMidDeepLeft = [centerX - width * 0.03, height * 0.65];
  const pMidDeepRight = [centerX + width * 0.04, height * 0.61];

  const makePath = (points: number[][]) => {
    return `M ${points.map((p) => `${p[0]} ${p[1]}`).join(" L ")} Z`;
  };

  const aboveFacets = [
    { pts: [pTop, pLeftWater, pMidAbove], opacity: 1.0 },
    { pts: [pTop, pMidAbove, pCenterWater], opacity: 0.85 },
    { pts: [pTop, pCenterWater, pMidAboveRight], opacity: 0.7 },
    { pts: [pTop, pMidAboveRight, pRightWater], opacity: 0.55 },
  ];

  const belowFacets = [
    { pts: [pLeftWater, pLeftBulge, pMidDeepLeft], opacity: 0.5 },
    { pts: [pLeftWater, pMidDeepLeft, pCenterWater], opacity: 0.65 },
    { pts: [pCenterWater, pMidDeepRight, pRightWater], opacity: 0.75 },
    { pts: [pRightWater, pRightBulge, pMidDeepRight], opacity: 0.9 },
    { pts: [pMidDeepLeft, pDeepTip, pMidDeepRight], opacity: 0.55 },
    { pts: [pLeftBulge, pDeepTip, pMidDeepLeft], opacity: 0.7 },
    { pts: [pRightBulge, pDeepTip, pMidDeepRight], opacity: 0.8 },
  ];

  // Helper to approximate the right edge of the iceberg at different layer levels
  const getIcebergRightEdge = (i: number) => {
    if (i === 0) return centerX + width * 0.03;
    if (i === 1) return centerX + width * 0.075;
    if (i === 2) return centerX + width * 0.11;
    return centerX + width * 0.035;
  };

  // Organic sine water wave movement path
  const waveAmplitude = 3;
  const waveFrequency = 0.04;
  const wavePoints = [];
  const waveHalfWidth = 140;
  for (let x = -waveHalfWidth; x <= waveHalfWidth; x += 5) {
    const angle = x * waveFrequency + frame * 0.08;
    const yOffset = Math.sin(angle) * waveAmplitude;
    const xCoord = centerX + x * (waterWidth / (waveHalfWidth * 2));
    wavePoints.push([xCoord, waterlineY + yOffset]);
  }
  const wavePath = `M ${wavePoints.map((p) => `${p[0]} ${p[1]}`).join(" L ")}`;

  return (
    <AbsoluteFill style={{ backgroundColor: bgGradient, overflow: "hidden" }}>
      {/* Cinematic Camera Wrapper */}
      <div
        style={{
          width: "100%",
          height: "100%",
          transform: `scale(${cameraScale})`,
          transition: "none",
        }}
      >
        {/* Submerged Ocean Depth Glow (Reveals dynamically) */}
        <div
          style={{
            position: "absolute",
            top: waterlineY,
            left: 0,
            width: width,
            height: height - waterlineY,
            background: "linear-gradient(to bottom, #112d4e00 0%, #0c2242cc 30%, #031024fc 100%)",
            opacity: waterDepthOpacity,
            pointerEvents: "none",
            transition: "none",
          }}
        />

        {/* Global Blueprint Grid Lines for Technical Presentation */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundImage:
              "radial-gradient(rgba(255,255,255,0.02) 1px, transparent 0)",
            backgroundSize: "24px 24px",
            opacity: 0.8,
            pointerEvents: "none",
          }}
        />

        {/* Main Header Presentation */}
        <div
          style={{
            position: "absolute",
            top: height * 0.06,
            left: width * 0.05,
            right: width * 0.05,
            display: "flex",
            justifyContent: "space-between",
            alignItems: "flex-end",
            borderBottom: "1px solid rgba(255, 255, 255, 0.08)",
            paddingBottom: height * 0.02,
            transition: "none",
          }}
        >
          <div>
            <h1
              style={{
                fontFamily: montserratFamily,
                color: "#ffffff",
                fontSize: "2.4rem",
                margin: 0,
                fontWeight: 800,
                letterSpacing: "1px",
              }}
            >
              {titleText}
            </h1>
            <p
              style={{
                fontFamily: interFamily,
                color: "#94a3b8",
                fontSize: "1.05rem",
                margin: "4px 0 0 0",
                fontWeight: 400,
              }}
            >
              {subtitleText}
            </p>
          </div>
          <div
            style={{
              fontFamily: interFamily,
              color: waterlineColor,
              fontSize: "0.85rem",
              fontWeight: 700,
              letterSpacing: "3px",
              textTransform: "uppercase",
            }}
          >
            Systems Thinking Explainer
          </div>
        </div>

        {/* Dynamic Vector Core Elements */}
        <svg
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: width,
            height: height,
            pointerEvents: "none",
          }}
        >
          {/* Below Water Iceberg (Translucent faceting) */}
          <g
            style={{
              opacity: belowOpacity,
              transform: `scale(${belowScaleX}, ${belowScaleY})`,
              transformOrigin: `${centerX}px ${waterlineY}px`,
              transition: "none",
            }}
          >
            {belowFacets.map((f, i) => (
              <path
                key={`below-${i}`}
                d={makePath(f.pts)}
                fill={icebergColorBelow}
                fillOpacity={f.opacity}
                stroke={waterlineColor}
                strokeWidth={1.5}
                strokeOpacity={0.25}
                style={{ transition: "none" }}
              />
            ))}
          </g>

          {/* Above Water Iceberg (Bright crystalline faceting) */}
          <g
            style={{
              transform: `scale(${aboveScale}) translate3d(0, ${aboveY}px, 0)`,
              transformOrigin: `${centerX}px ${waterlineY}px`,
              transition: "none",
            }}
          >
            {aboveFacets.map((f, i) => (
              <path
                key={`above-${i}`}
                d={makePath(f.pts)}
                fill={icebergColorAbove}
                fillOpacity={f.opacity}
                stroke="#ffffff"
                strokeWidth={1.5}
                strokeOpacity={0.6}
                style={{ transition: "none" }}
              />
            ))}
          </g>

          {/* Depth Axis / Meter Left side */}
          <g style={{ opacity: waterOpacity, transition: "none" }}>
            <line
              x1={width * 0.05}
              y1={waterlineY}
              x2={width * 0.05}
              y2={height * 0.88}
              stroke="rgba(255, 255, 255, 0.15)"
              strokeWidth={1}
              style={{ transition: "none" }}
            />
            {resolvedLayers.map((_, index) => {
              const cardY =
                height * 0.18 +
                (index * (height * 0.68)) / Math.max(1, resolvedLayers.length - 1);
              const activeFocus = getFocusWeight(index);
              const color = index === 0 ? icebergColorAbove : waterlineColor;

              return (
                <g key={`tick-${index}`} style={{ transition: "none" }}>
                  <line
                    x1={width * 0.045}
                    y1={cardY}
                    x2={width * 0.05}
                    y2={cardY}
                    stroke={activeFocus > 0.4 ? color : "rgba(255, 255, 255, 0.3)"}
                    strokeWidth={activeFocus > 0.4 ? 2 : 1}
                    style={{ transition: "none" }}
                  />
                  {activeFocus > 0.1 && (
                    <circle
                      cx={width * 0.05}
                      cy={cardY}
                      r={3}
                      fill={color}
                      style={{
                        opacity: activeFocus,
                        filter: `drop-shadow(0 0 3px ${color})`,
                        transition: "none",
                      }}
                    />
                  )}
                </g>
              );
            })}
          </g>

          {/* Connection Lines from Iceberg Facets to Content Cards */}
          {resolvedLayers.map((_, index) => {
            const cardY =
              height * 0.18 +
              (index * (height * 0.68)) / Math.max(1, resolvedLayers.length - 1);
            const stagger = layerStaggers[index];
            const x1 = getIcebergRightEdge(index);
            const x2 = width * 0.44;

            // Compute connection progress
            const activeX2 = interpolate(stagger, [0.3, 1], [x1, x2], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });
            const lineOpacity = interpolate(stagger, [0, 1], [0, 0.35], {
              extrapolateRight: "clamp",
            });
            const focus = getFocusWeight(index);
            const color = index === 0 ? icebergColorAbove : waterlineColor;

            return (
              <g key={`conn-${index}`} style={{ transition: "none" }}>
                {/* Background dashed blueprint guide line */}
                <line
                  x1={x1}
                  y1={cardY}
                  x2={x2}
                  y2={cardY}
                  stroke="rgba(255, 255, 255, 0.05)"
                  strokeWidth={1}
                  strokeDasharray="4 4"
                  style={{ transition: "none" }}
                />
                {/* Active drawing connecting line */}
                <line
                  x1={x1}
                  y1={cardY}
                  x2={activeX2}
                  y2={cardY}
                  stroke={color}
                  strokeWidth={focus > 0.4 ? 2 : 1}
                  style={{
                    opacity: focus > 0.4 ? 0.8 : lineOpacity,
                    transition: "none",
                  }}
                />
                {/* End glow dot at Card container */}
                {stagger > 0.9 && (
                  <circle
                    cx={x2}
                    cy={cardY}
                    r={focus > 0.4 ? 4 : 2}
                    fill={color}
                    style={{
                      opacity: interpolate(stagger, [0.8, 1], [0, 1]),
                      filter: `drop-shadow(0 0 4px ${color})`,
                      transition: "none",
                    }}
                  />
                )}
              </g>
            );
          })}

          {/* Glowing Animated Wave Line on Water Surface */}
          {waterWidth > 0 && (
            <path
              d={wavePath}
              fill="none"
              stroke={waterlineColor}
              strokeWidth={3}
              strokeLinecap="round"
              style={{
                opacity: waterOpacity,
                filter: `drop-shadow(0 0 8px ${waterlineColor})`,
                transition: "none",
              }}
            />
          )}
        </svg>

        {/* Sidebar Cards Panel (Interactive Layers explanation) */}
        <div style={{ transition: "none" }}>
          {resolvedLayers.map((layer, index) => {
            const stagger = layerStaggers[index];
            const focus = getFocusWeight(index);

            // Positioning relative to vertical distribution matching the vector height
            const cardY =
              height * 0.18 +
              (index * (height * 0.68)) / Math.max(1, resolvedLayers.length - 1);
            const cardHeight = height * 0.15;

            // Entrance movement values
            const scale = interpolate(stagger, [0, 1], [0.94, 1], {
              extrapolateRight: "clamp",
            });
            const opacity = interpolate(stagger, [0, 1], [0, 1], {
              extrapolateRight: "clamp",
            });
            const tx = interpolate(stagger, [0, 1], [40, 0], {
              extrapolateRight: "clamp",
            });

            // Dynamic Styling based on current focus
            const cardAccentColor = index === 0 ? icebergColorAbove : waterlineColor;
            const currentTitleColor = interpolateColors(
              focus,
              [0.25, 1],
              ["#ffffff", highlightColor]
            );
            const cardBorder = focus > 0.4
              ? `1px solid rgba(61, 242, 255, ${0.15 + focus * 0.3})`
              : "1px solid rgba(255, 255, 255, 0.05)";
            const cardBg = focus > 0.4
              ? `rgba(13, 37, 75, ${0.45 + focus * 0.15})`
              : "rgba(255, 255, 255, 0.02)";
            const glowShadow = focus > 0.4
              ? `0 10px 30px rgba(61, 242, 255, ${focus * 0.08})`
              : "none";

            return (
              <div
                key={`card-${index}`}
                style={{
                  position: "absolute",
                  left: width * 0.46,
                  top: cardY - cardHeight / 2,
                  width: width * 0.47,
                  height: cardHeight,
                  boxSizing: "border-box",
                  transform: `scale(${scale}) translate3d(${tx}px, 0, 0)`,
                  opacity: opacity,
                  background: cardBg,
                  borderRadius: "8px",
                  border: cardBorder,
                  boxShadow: glowShadow,
                  display: "flex",
                  flexDirection: "row",
                  overflow: "hidden",
                  transition: "none",
                }}
              >
                {/* Visual Active Progress Line Badge */}
                <div
                  style={{
                    width: "5px",
                    height: `${interpolate(stagger, [0, 1], [0, 100], { extrapolateRight: "clamp" })}%`,
                    backgroundColor: cardAccentColor,
                    alignSelf: "center",
                    transition: "none",
                  }}
                />

                {/* Inner Card Content */}
                <div
                  style={{
                    flex: 1,
                    padding: `${height * 0.018}px ${width * 0.02}px`,
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                    transition: "none",
                  }}
                >
                  {/* Layer Meta Header */}
                  <div
                    style={{
                      display: "flex",
                      flexDirection: "row",
                      justifyContent: "space-between",
                      alignItems: "center",
                      marginBottom: "4px",
                      transition: "none",
                    }}
                  >
                    <span
                      style={{
                        fontFamily: montserratFamily,
                        fontSize: "0.75rem",
                        fontWeight: 800,
                        letterSpacing: "2px",
                        color: cardAccentColor,
                      }}
                    >
                      {layer.depthLabel}
                    </span>
                    <span
                      style={{
                        fontFamily: montserratFamily,
                        fontSize: "0.8rem",
                        fontWeight: 700,
                        color: "rgba(255, 255, 255, 0.3)",
                      }}
                    >
                      0{index + 1}
                    </span>
                  </div>

                  {/* Main Header Row */}
                  <h2
                    style={{
                      fontFamily: montserratFamily,
                      fontSize: "1.45rem",
                      fontWeight: 700,
                      color: currentTitleColor,
                      margin: 0,
                    }}
                  >
                    {layer.title}
                  </h2>

                  {/* Dynamic Help Subtitle */}
                  <p
                    style={{
                      fontFamily: interFamily,
                      fontSize: "0.9rem",
                      fontWeight: 600,
                      fontStyle: "italic",
                      color: "#94a3b8",
                      margin: "2px 0 6px 0",
                    }}
                  >
                    {layer.subtitle}
                  </p>

                  {/* Detailed Description */}
                  <p
                    style={{
                      fontFamily: interFamily,
                      fontSize: "0.92rem",
                      lineHeight: "1.4",
                      color: "rgba(226, 232, 240, 0.85)",
                      margin: 0,
                      fontWeight: 400,
                    }}
                  >
                    {layer.description}
                  </p>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default IcebergModel;